var t=`1184-pico-de-gallo`;var n=`world-1184`;var a=`MX`;var r=`central-america-caribbean`;var s=4;var o=26;var d={en:`Pico de Gallo`,ua:`Піко де гальйо`};var l={en:`Pico de Gallo is a dish from Mexico prepared with tomato, white onion, serrano pepper, cilantro. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Піко де гальйо, страва кухні країни Мексика, яку готують із таких продуктів: помідор, біла цибуля, перець серрано, кінза. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var p=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:11,i:[[`tomato`,500,`g`],[`white-onion`,200,`g`],[`serrano-pepper`,2,`pcs`],[`cilantro`,45,`g`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:5,i:[[`lime-juice`,65,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Serve the dish at the intended temperature and garnish as needed with previously prepared ingredients.`,ua:`Подавайте страву за відповідної температури й прикрашайте раніше підготовленими складниками.`,t:[`garnishing`],m:10,i:[]}];var h={slug:t,id:n,country:`MX`,region:r,servings:4,minutes:26,title:d,text:l,steps:p};export{a as country,h as default,n as id,o as minutes,r as region,s as servings,t as slug,p as steps,l as text,d as title};